> Thanks! It looks good, could we find a way to reduce the duplicate code?

@yewentao256 As far as i can see, defining another macro like following can reduce duplicate code. But i am not sure if it is a good idea.

```
#define MOE_SUM_CASE(TOPK)                                                     \
  case TOPK:                                                                   \
    VLLM_STABLE_DISPATCH_FLOATING_TYPES(                                       \
        input.scalar_type(), "moe_sum_kernel", [&] {                           \
          vllm::moe::moe_sum_kernel<scalar_t, TOPK><<<grid, block, 0, stream>>>( \
              reinterpret_cast<scalar_t*>(output.mutable_data_ptr()),           \
              reinterpret_cast<const scalar_t*>(input.const_data_ptr()),        \
              hidden_size);                                                     \
        });                                                                     \
    break

// switch 部分变为:
switch (topk) {
    MOE_SUM_CASE(2);
    MOE_SUM_CASE(3);
    MOE_SUM_CASE(4);
    MOE_SUM_CASE(5);
    MOE_SUM_CASE(6);
    MOE_SUM_CASE(7);
    MOE_SUM_CASE(8);
    default:
      torch::stable::sum_out(output, input, std::array<int64_t, 1>{1});
      break;
}
```

